    border-color: #ffff00 !important;
    background-color: #ffff00 !important;
    color: #ffff00 !important;
}

/* buttons and selects: black ground, yellow trace, pill */
button:not(#sk-never), select:not(#sk-never),
[role="button"]:not(#sk-never), [role="tab"]:not(#sk-never),
[role="switch"]:not(#sk-never), input[type="submit"]:not(#sk-never),
input[type="button"]:not(#sk-never), input[type="reset"]:not(#sk-never) {
    background-color: #000000 !important;
    color: #ffff00 !important;
    outline: 1px solid #ffff00 !important;
    outline-offset: -1px !important;
}

/* ⚠ The pill is chrome, and only a chrome-sized control should wear it. A 624x351
   `<div role="button">` wrapping a <video> is a control by ARIA and a picture by
   every other measure, and 999px turns it into an ellipse — the poster is clipped to
   an oval and the <video> inherits the radius with it, so the whole player goes.
   Spared by the same two tests the background image is spared by:
   a name that says picture, or a media child. The void input forms cannot hold a
   child at all, so they keep the pill unconditionally. */
button:not(#sk-never):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]):not(:has(> img, > picture, > video, > canvas, > object, > embed, > iframe)),
select:not(#sk-never):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]):not(:has(> img, > picture, > video, > canvas, > object, > embed, > iframe)),
[role="button"]:not(#sk-never):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]):not(:has(> img, > picture, > video, > canvas, > object, > embed, > iframe)),
[role="tab"]:not(#sk-never):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]):not(:has(> img, > picture, > video, > canvas, > object, > embed, > iframe)),
[role="switch"]:not(#sk-never):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]):not(:has(> img, > picture, > video, > canvas, > object, > embed, > iframe)),
input[type="submit"]:not(#sk-never),
input[type="button"]:not(#sk-never),
input[type="reset"]:not(#sk-never) {
    border-radius: 999px !important;
}

/* A control's background image is a gloss gradient, and colour paints behind an
   image rather than over it, so without this the button stays white — that is what
   left the Search button light on forum.mobilism.org even once it was targeted.
   EXCEPT when the control is empty, and then the image is the only label it has:
   reCAPTCHA's reload, audio and info controls are 48x48 <button>s carrying
   `background: url(refresh_2x.png)` and nothing at all inside, so stripping it left
   three blank rings and no way to ask for a new challenge. An icon drawn as an
   inline <svg> child never enters into it: a child makes the button non-empty.
   EXCEPT, again, when the class says the background is a picture: a player's poster
   frame is exactly that — a background image on a <button> that is not empty,
   because it holds the play arrow. `:empty` cannot see it; the name can. */
