select:not(#sk-never):not(:empty):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]),
[role="button"]:not(#sk-never):not(:empty):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]),
[role="tab"]:not(#sk-never):not(:empty):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]),
[role="switch"]:not(#sk-never):not(:empty):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]) {
    background-image: none !important;
}

/* the button-shaped inputs are void elements, so `:empty` is always true of them
   and can say nothing; their label is the `value`, never a picture */
input[type="submit"]:not(#sk-never), input[type="button"]:not(#sk-never),
input[type="reset"]:not(#sk-never) {
    background-image: none !important;
}

/* And such an icon is drawn on transparency — reCAPTCHA's is pure #000 — so on a
   black button it would be exactly as gone as when we were erasing it. Same answer
   as `ui: image-ground`, and the same mid grey, for the same reason: it is the one
   value where neither dark nor light ink can disappear. Elements whose class says
   `icon` are left out, because those draw the glyph with `color`, already yellow. */
button:not(#sk-never):empty:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]),
select:not(#sk-never):empty:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]),
[role="button"]:not(#sk-never):empty:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]),
[role="tab"]:not(#sk-never):empty:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]),
[role="switch"]:not(#sk-never):empty:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]) {
    background-color: #808080 !important;
}

/* the same treatment for links that act as buttons */
a[href^="javascript:" i]:not(#sk-never):not(#sk-never),
a[class*="btn" i]:not(#sk-never):not(#sk-never),
a[class*="button" i]:not(#sk-never):not(#sk-never) {
    background-color: #000000 !important;
    background-image: none !important;
    color: #ffff00 !important;
    outline: 1px solid #ffff00 !important;
    outline-offset: -1px !important;
    border-radius: 999px !important;
    padding: 0.25em 0.9em !important;
}

/* single-line text entry: a yellow pill, traced rather than filled. The outline
   follows border-radius, and being an outline it adds no layout of its own — only
   the padding does, which the rounded ends need so text is not clipped. */
input:not(#sk-never):is([type=text], [type=search], [type=email], [type=url], [type=tel],
  [type=password], [type=number], [type=date], [type=datetime-local],
  :not([type])) {
    background-color: #000000 !important;
    background-image: none !important;
    color: #ffff00 !important;
    caret-color: #ffff00 !important;
    border: none !important;
    border-radius: 999px !important;
    outline: 1px solid #ffff00 !important;
    outline-offset: -1px !important;
}

/* ⚠ and the padding ONLY where the field has nothing else in it. A site that pads a
   field generously is usually making room for a leading icon, and overriding that
   with a smaller value walks the text straight underneath it: Piano pads its login
   field for the envelope, we cut it to 0.7em, and the first characters of what you
   type disappear behind the glyph. CSS cannot say "at least this much" — padding
   has no access to its own current value — so the only safe move is not to touch a
   field that has an adornment to make room for.
   The test is on the PARENT's children rather than on the input's later siblings,
   which catches a leading icon written before the input as well as after it. Being
   greedy costs nothing here, unlike everywhere else in this file: over-matching only
   means a field keeps the padding the site chose, which is by definition what the
   site wanted. */
*:not(:has(> :is(span, label, i, svg, img))):not(#sk-never) > input:not(#sk-never):is([type=text], [type=search], [type=email], [type=url], [type=tel],
  [type=password], [type=number], [type=date], [type=datetime-local],
  :not([type])) {
    padding-left: 0.7em !important;
    padding-right: 0.7em !important;
}

input:not(#sk-never)::placeholder {
    color: #999900 !important;
}

/* a textarea is not a pill — it keeps the traced-box treatment */
textarea:not(#sk-never) {
    background-color: #000000 !important;
    background-image: none !important;
    color: #ffff00 !important;
    caret-color: #ffff00 !important;
    outline: 1px solid #ffff00 !important;
    outline-offset: -1px !important;
}

textarea:not(#sk-never)::placeholder {
    color: #999900 !important;
}

input:not(#sk-never):is([type=checkbox], [type=radio]) {
    accent-color: #ffff00 !important;
}

button:not(#sk-never):hover,
[role="button"]:not(#sk-never):hover,
input:not(#sk-never):is([type=submit], [type=button]):hover,
a[href^="javascript:" i]:not(#sk-never):not(#sk-never):hover,
a[class*="btn" i]:not(#sk-never):not(#sk-never):hover,
a[class*="button" i]:not(#sk-never):not(#sk-never):hover {
    background-color: #ffff00 !important;
    color: #000000 !important;
}

/* ⚠ The filled part of a value bar, which is empty because its content is its
   geometry — see VALUE_BARS. Left alone it is swept transparent by `ui: overlays`
   and sits on a track `bg all` painted black, so the number it carries is simply
   gone: a volume slider opened as a black rectangle. Only the level is coloured;
   the track stays black, and yellow on black is the boundary back. */
*:empty:not(#sk-never):not(#sk-never):not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]):not(img, picture, video, canvas, object, embed, iframe):not(button, input, select, textarea, option, optgroup, progress, meter, summary, [role="button"], [role="tab"], [role="menuitem"], [role="switch"], [role="checkbox"], [role="radio"]):is([class*="volume" i], [class*="progress" i], [class*="scrub" i], [class*="seek" i], [class*="slider" i], [class*="played" i], [class*="buffer" i], [class*="meter" i], [class*="gauge" i], [class*="level" i], [role="progressbar"], [role="slider"]),
:is([class*="volume" i], [class*="progress" i], [class*="scrub" i], [class*="seek" i], [class*="slider" i], [class*="played" i], [class*="buffer" i], [class*="meter" i], [class*="gauge" i], [class*="level" i], [role="progressbar"], [role="slider"]):not(#sk-never) > *:empty:not(#sk-never):not(#sk-never):not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]):not(img, picture, video, canvas, object, embed, iframe):not(button, input, select, textarea, option, optgroup, progress, meter, summary, [role="button"], [role="tab"], [role="menuitem"], [role="switch"], [role="checkbox"], [role="radio"]) {
    background-color: #ffff00 !important;
}

img:not(#sk-never), picture:not(#sk-never),
object:not(#sk-never), embed:not(#sk-never) {
    background-color: #808080 !important;
    filter: none !important;
}

/* An empty link is the other half of `an empty control's picture is its label`.
   A wordmark drawn as an empty <a> with the PNG as its background, under a
   CSS-in-JS hash for a class, gives ART no word to match at all: the name
   heuristic has run out. Being empty and interactive is the whole tell.
   And the grey has to come with it: that wordmark is dark navy, so handing the
   picture back on black would leave it just as invisible. An empty link that has no
   picture cannot show a grey box either — with no content it has no width to fill,
   unless the page sized it, and a page only sizes an empty link to hold a picture. */
a:not(#sk-never):empty:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]),
[role="link"]:not(#sk-never):empty:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]) {
    background-color: #808080 !important;
}

*:empty:not(#sk-never):not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]):not(img, picture, video, canvas, object, embed, iframe):not(button, input, select, textarea, option, optgroup, progress, meter, summary, [role="button"], [role="tab"], [role="menuitem"], [role="switch"], [role="checkbox"], [role="radio"]):not(a, [role="link"]):not([class*="logo" i], [class*="brand" i], [class*="badge" i], [class*="avatar" i], [class*="sprite" i], [class*="flag" i], [class*="thumb" i], [class*="img" i], [class*="photo" i], [class*="picture" i], [class*="poster" i], [class*="preview" i], [class*="cover" i]) {
    background-image: none !important;
}

[class*="overlay" i]:not(#sk-never):not(#sk-never),
[class*="backdrop" i]:not(#sk-never):not(#sk-never),
[class*="scrim" i]:not(#sk-never):not(#sk-never),
span[class*="ripple" i]:not(#sk-never):not(#sk-never) {
    background-color: transparent !important;
}

/* a control's own floating label, and whatever it carries */
:is(input, textarea, select):not(#sk-never) ~ :is(span, label):not(#sk-never),
:is(input, textarea, select):not(#sk-never) ~ :is(span, label):not(#sk-never) *:not(#sk-never) {
    background-color: transparent !important;
}

/* ⚠ The fourth kind of layer, and the one that blanks a page outright: an EMPTY
   element left pinned over the viewport. Two sites went completely black on this,
   every pixel of them: a notification host (fixed, inset 0, z-index 1060,
   pointer-events none, no children) waiting for a toast that never comes, and a
   consent gate emptied on accept but never removed. Neither carries a word this
   style could match, and `pointer-events:none` hides such a layer from
   elementsFromPoint too, so they only surface in a paint diff.
   `:empty` is the discriminator, and it is the same one the rest of the file
   already trusts: an element with no content has nothing of its own to make
   legible, so painting it can only ever produce a sheet.
   Every exclusion is load-bearing. Controls: at (1,3,1) this would outrank the
   #808080 ground `ui: controls` gives an empty icon button. Media: <img>, <iframe>
   and <video> are :empty by definition and `ui: image-ground` must survive. Links:
